(() => {
  const rows = [
    {id:'knowledge', label:'01 / BUSINESS KNOWLEDGE', title:'Your expertise.<br>Ready for every question.', description:'Give your AI assistant the business information it needs, then shape and test how it responds.', benefits:['Organize your knowledge sources','Set instructions and a consistent tone','Test answers in the playground'], image:'feature-knowledge.png', alt:'Business founder reviewing documents beside her laptop', badge:'Your business, understood', chips:['Knowledge sources','Reply playground']},
    {id:'campaigns', label:'02 / CAMPAIGN AUDIENCES', title:'The right people.<br>The right moment.', description:'Turn your contact list into focused audiences and prepare campaigns around the customers you want to reach.', benefits:['Group contacts with tags and segments','Choose your campaign audience','Schedule sends and track recipients'], image:'feature-campaigns.png', alt:'Boutique owner preparing customer outreach on his phone', badge:'A more personal connection', chips:['Audience selected','Campaign scheduled']},
    {id:'social', label:'03 / SOCIAL PUBLISHING', title:'Show up.<br>Without the last-minute rush.', description:'Bring your social content into one publishing workflow, from the first draft to your planned posting date.', benefits:['Compose for connected social accounts','Preview your content before publishing','Plan posts with a publishing calendar'], image:'feature-social.png', alt:'Creative business owner photographing a product in her studio', badge:'Make room for your next idea', chips:['Content preview','Publishing calendar']}
  ];
  const section = document.createElement('section'); section.id='business-features'; section.className='human-features';
  section.innerHTML = `<div class="wrap"><header class="human-features-heading reveal"><div class="eyebrow">BUILT AROUND YOUR WORKDAY</div><h2>More space for<br>the work you love.</h2><p>A few more ways to bring your business together.</p></header>${rows.map((row,i)=>`<article class="human-feature-row ${i%2?'human-feature-reverse':''}" id="feature-${row.id}"><div class="human-feature-visual reveal"><img src="assets/${row.image}" alt="${row.alt}" width="1254" height="1254" loading="lazy" decoding="async"><div class="human-photo-badge"><span aria-hidden="true">✦</span>${row.badge}</div><div class="human-photo-chips">${row.chips.map((chip,j)=>`<span style="--chip-delay:${j*100}ms"><i aria-hidden="true">✓</i>${chip}</span>`).join('')}</div></div><div class="human-feature-copy reveal"><span class="human-feature-label">${row.label}</span><h3>${row.title}</h3><p>${row.description}</p><ul>${row.benefits.map(b=>`<li><span aria-hidden="true">✓</span>${b}</li>`).join('')}</ul></div></article>`).join('')}</div>`;
  const oldProduct=document.getElementById('product');
  oldProduct.before(section);
  for(const id of ['product','workflows','solutions']) document.getElementById(id)?.remove();
  document.querySelectorAll('a[href="#product"],a[href="#workflows"]').forEach(a=>a.href='#product-story');
  document.querySelectorAll('a[href="#solutions"]').forEach(a=>a.href='#business-features');
})();
